import json,subprocess
rows=json.load(open('final_rows.json'))
pts={p['id']:p for p in json.load(open('patients.json'))['resources']}
ecgt={e['ecg']:e['time'] for e in json.load(open('ecg_all.json'))['ecgs']}
CH={'NEW_AF':'new atrial fibrillation','RESOLVED_AF':'resolution of the previous atrial fibrillation',
 'NEW_ATRIAL_FLUTTER':'new atrial flutter','RESOLVED_ATRIAL_FLUTTER':'resolution of atrial flutter',
 'NEW_BUNDLE_BRANCH_BLOCK':'a new bundle branch block','RESOLVED_BUNDLE_BRANCH_BLOCK':'resolution of the previously present bundle branch block',
 'QTC_INCREASE_60':'a QTc increase of 60 ms or more','QTC_DECREASE_60':'a QTc decrease of 60 ms or more'}
RD={'SINUS':'sinus rhythm','AF':'atrial fibrillation','ATRIAL_FLUTTER':'atrial flutter','PACED':'paced rhythm','OTHER':'other rhythm'}
out=[]
for x in rows:
    e=x['ecg']
    parts=[]
    parts.append("ECG %s recorded %s."%(e,ecgt[e]))
    if x['rhythm']=='SINUS':
        rr="Regular P waves with a constant PR interval precede every QRS complex, so the rhythm is sinus"
        if x['ventricular_rate']>=100: rr+=" (sinus tachycardia)"
        elif x['ventricular_rate']<60: rr+=" (sinus bradycardia)"
        rr+=" at %d/min."%x['ventricular_rate']
    elif x['rhythm']=='AF':
        rr="Irregularly irregular ventricular response at a mean rate of %d/min with no organised or reproducible P waves before the QRS complexes: atrial fibrillation. No measurable PR interval."%x['ventricular_rate']
    elif x['rhythm']=='ATRIAL_FLUTTER':
        rr="Regular narrow-complex tachycardia at %d/min with negative sawtooth atrial waves in II/III/aVF and positive flutter waves in V1 at about twice the ventricular rate (roughly 280/min): typical atrial flutter with 2:1 conduction. No measurable PR interval."%x['ventricular_rate']
    parts.append(rr)
    iv="Intervals: "
    iv+=("PR %d ms, "%x['pr_ms']) if x['pr_ms'] is not None else "PR not measurable, "
    iv+="QRS %d ms, QT %d ms, Bazett QTc %d ms."%(x['qrs_ms'],x['qt_ms'],x['qtc_ms'])
    parts.append(iv)
    parts.append("Frontal QRS axis about %+d degrees (%s)."%(round(x['axis_deg']),x['axis']))
    if x['conduction']:
        cd=[]
        if 'FIRST_DEGREE_AV_BLOCK' in x['conduction']: cd.append("first-degree AV block (PR %d ms)"%x['pr_ms'])
        if 'LBBB' in x['conduction']: cd.append("left bundle branch block (QRS %d ms, rS/QS in V1-V2 with a broad monophasic R in I, aVL and V6)"%x['qrs_ms'])
        if 'RBBB' in x['conduction']: cd.append("right bundle branch block (QRS %d ms, terminal R' in V1 with a broad terminal S in I and V6)"%x['qrs_ms'])
        parts.append("Conduction: "+"; ".join(cd)+".")
    else:
        parts.append("QRS duration is under 120 ms with no bundle branch block pattern and the PR interval is 200 ms or less, so no conduction abnormality.")
    if x['prior'] is None:
        parts.append("There is no earlier ECG for this patient, so no comparison is possible.")
    else:
        if x['changes']:
            parts.append("Compared with the previous ECG %s (%s, %s at %d/min, QRS %d ms, QTc %d ms): %s."%(
                x['prior'],ecgt[x['prior']][:10],RD[x['prev_rhythm']],x['prev_rate'],round(x['prev_qrs']),x['prev_qtc'],
                ", ".join(CH[c] for c in x['changes'])))
        else:
            parts.append("Compared with the previous ECG %s (%s, %s at %d/min, QRS %d ms, QTc %d ms) there is no significant change: same rhythm, no new or resolved bundle branch block and QTc within 60 ms."%(
                x['prior'],ecgt[x['prior']][:10],RD[x['prev_rhythm']],x['prev_rate'],round(x['prev_qrs']),x['prev_qtc']))
    body={"patient":x['patient'],"ecg":e,"rhythm":x['rhythm'],"ventricular_rate":x['ventricular_rate'],
          "pr_ms":x['pr_ms'],"qrs_ms":x['qrs_ms'],"qtc_ms":x['qtc_ms'],"axis":x['axis'],
          "conduction":x['conduction'],"prior_ecg":x['prior'],"changes":x['changes'],
          "explanation":" ".join(parts)}
    out.append(body)
json.dump(out,open('interp_payload.json','w'),indent=1)
print(len(out)); print(json.dumps(out[0],indent=1))
